// ✗ 有问题的 DCL（JDK 5 之前被认为"没问题"，其实是错的）
class Singleton {
    private static Singleton instance;          // 少了 volatile

    static Singleton get() {
        if (instance == null) {                 // ① 第一次检查（无锁）
            synchronized (Singleton.class) {
                if (instance == null) {         // ② 第二次检查
                    instance = new Singleton(); // ③ 这行不是原子操作！
                }
            }
        }
        return instance;
    }
}

// ③ 实际被拆成三步（JIT 可重排 2 和 3）：
//   memory = allocate();      // 1. 分配内存
//   ctorSingleton(memory);    // 2. 初始化对象
//   instance = memory;        // 3. 引用赋值
// 若 2、3 重排 → 线程 B 在 ① 看到非 null，直接返回一个「半初始化」对象

// ✓ 正确写法
class Singleton2 {
    private static volatile Singleton2 instance;  // volatile 禁止 2/3 重排

    static Singleton2 get() {
        Singleton2 local = instance;              // 局部变量：减少 volatile 读次数
        if (local == null) {
            synchronized (Singleton2.class) {
                local = instance;
                if (local == null) {
                    instance = local = new Singleton2();
                }
            }
        }
        return local;
    }
}

