// 第一层:直接用 Unsafe(了解原理,业务代码不要这么写)
class UnsafeCounter {
    private static final Unsafe U;
    private static final long OFFSET;      // value 字段在对象内的偏移量
    private volatile int value;

    static {
        try {
            Field f = Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            U = (Unsafe) f.get(null);
            OFFSET = U.objectFieldOffset(UnsafeCounter.class.getDeclaredField("value"));
        } catch (Exception e) {
            throw new Error(e);
        }
    }

    int incrementAndGet() {
        int old;
        do {
            old = value;                              // ① 每次循环都重读
        } while (!U.compareAndSwapInt(this, OFFSET, old, old + 1));  // ② 失败就再来
        return old + 1;
    }
}

// 第二层:AtomicInteger(内部就是上面那套,只是封装好了)
