// 第三层:VarHandle(JDK 9+,标准 API,无需 Unsafe)
class VarHandleCounter {
    private volatile int value;
    private static final VarHandle VH;
    static {
        try {
            VH = MethodHandles.lookup()
                    .findVarHandle(VarHandleCounter.class, "value", int.class);
        } catch (ReflectiveOperationException e) {
            throw new Error(e);
        }
    }
    int incrementAndGet() {
        int old;
        do {
            old = (int) VH.getVolatile(this);
        } while (!VH.compareAndSet(this, old, old + 1));
        return old + 1;
    }
}

// 非公平锁的 tryAcquire（NonfairSync）
final boolean nonfairTryAcquire(int acquires) {
    final Thread current = Thread.currentThread();
    int c = getState();
    if (c == 0) {
        if (compareAndSetState(0, acquires)) {     // ← 直接抢，不看队列
            setExclusiveOwnerThread(current);
            return true;
        }
    } else if (current == getExclusiveOwnerThread()) {
        setState(c + acquires);                    // 重入
        return true;
    }
    return false;
}

// 公平锁的 tryAcquire（FairSync）
protected final boolean tryAcquire(int acquires) {
    final Thread current = Thread.currentThread();
    int c = getState();
    if (c == 0) {
        if (!hasQueuedPredecessors() &&             // ← 就多这一行！
            compareAndSetState(0, acquires)) {
            setExclusiveOwnerThread(current);
            return true;
        }
    } else if (current == getExclusiveOwnerThread()) {
        setState(c + acquires);
        return true;
    }
    return false;
}

// hasQueuedPredecessors 的实现（就是判断「有没有人在我前面排队」）
public final boolean hasQueuedPredecessors() {
    Node h = head, s = h.next, t = tail;
    if (h != t && s != null && s.thread != Thread.currentThread())
        return true;      // 队列非空，且队首不是我
    return false;
}

