public void execute(Runnable command) {
    if (command == null) throw new NullPointerException();
    int c = ctl.get();

    // ① 未达核心数:直接建核心线程
    if (workerCountOf(c) < corePoolSize) {
        if (addWorker(command, true)) return;
        c = ctl.get();                       // addWorker 失败(如池已关闭),重读状态
    }

    // ② 池仍在 RUNNING:尝试入队
    if (isRunning(c) && workQueue.offer(command)) {
        int recheck = ctl.get();
        if (!isRunning(recheck) && remove(command))
            reject(command);                 // 入队后池被关闭 → 移除并拒绝
        else if (workerCountOf(recheck) == 0)
            addWorker(null, false);          // 队列有任务但没线程 → 补一个
    }
    // ③ 入队失败(队列满):扩到最大线程数
    else if (!addWorker(command, false))
        // ④ 扩容也失败:拒绝
        reject(command);
}

// addWorker 里的关键一段(保证不超限)
private boolean addWorker(Runnable firstTask, boolean core) {
    retry:
    for (;;) {
        int c = ctl.get();
        int wc = workerCountOf(c);
        // 核心线程看 corePoolSize,非核心看 maximumPoolSize
        if (wc >= CAPACITY ||
            wc >= (core ? corePoolSize : maximumPoolSize))
            return false;
        if (compareAndIncrementWorkerCount(c))   // CAS 递增线程数
            break retry;
        // CAS 失败 → 重读 ctl 继续(可能状态变了或数满了)
    }
    // ... 创建 Worker、启动线程
}

