// 模拟两个请求，共用一个只有 1 个线程的池
public static void main(String[] args) throws Exception {
    ExecutorService pool = Executors.newFixedThreadPool(1);   // 故意只用 1 个线程

    // 请求 1：用户 A —— 忘了 remove
    pool.submit(() -> {
        USER.set("user-A");
        System.out.println("req1 sees: " + USER.get());   // user-A
        // 缺少 USER.remove()
    }).get();

    // 请求 2：用户 B —— 还没 set，先读一下（比如打了条日志）
    pool.submit(() -> {
        System.out.println("req2 sees: " + USER.get());   // ← 输出 user-A ！越权预演
        USER.set("user-B");
        System.out.println("req2 after set: " + USER.get());
    }).get();

    pool.shutdown();
}

