// ✓ 修法：提交任务时统一包装（框架里就是拦截器/AOP 做的事）
static Runnable wrap(Runnable task, String user) {
    return () -> {
        try {
            USER.set(user);
            task.run();
        } finally {
            USER.remove();          // 任务结束必清
        }
    };
