// ① 饿汉式：靠类初始化保证线程安全（JVM 保证 clinit 只跑一次）
class Eager {
    private static final Eager INSTANCE = new Eager();
    private Eager() {}
    static Eager get() { return INSTANCE; }
}

// ② 静态内部类：延迟加载 + 线程安全 + 无锁（非枚举里推荐这个）
class Holder {
    private Holder() {}
    private static class H { static final Holder INSTANCE = new Holder(); }
    static Holder get() { return H.INSTANCE; }
}

// ③ 枚举：《Effective Java》推荐，防反射、防反序列化破坏
enum EnumSingleton {
    INSTANCE;
    void doWork() { }
}

// ④ 双重检查锁：只在「必须延迟加载 + 必须传参 + 不能用枚举」时才写
class Dcl {
    private static volatile Dcl instance;      // volatile 不能省
    private Dcl() {}
    static Dcl get() {
        Dcl local = instance;                  // 局部变量少读一次 volatile
        if (local == null) {
            synchronized (Dcl.class) {
                local = instance;
                if (local == null) instance = local = new Dcl();
            }
        }
        return local;
    }
}

// ⑤ 需要传参：静态初始化块 + 一次性开关
class ConfigSingleton {
    private static final AtomicBoolean INITED = new AtomicBoolean();
    private static volatile ConfigSingleton instance;
    private ConfigSingleton(Config c) { /* ... */ }
    static void init(Config c) {
        if (!INITED.compareAndSet(false, true)) throw new IllegalStateException("already inited");
        instance = new ConfigSingleton(c);
    }
    static ConfigSingleton get() {
        if (instance == null) throw new IllegalStateException("not inited");
        return instance;
    }
}

