class BoundedQueue<T> {
    private final Object[] items;
    private int head, tail, count;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    BoundedQueue(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException();
        items = new Object[capacity];
    }

    void put(T item) throws InterruptedException {
        Objects.requireNonNull(item);
        lock.lockInterruptibly();              // 可中断，避免永久阻塞
        try {
            while (count == items.length) {    // while 而非 if
                notFull.await();               // 满：等「不满」这个条件
            }
            items[tail] = item;
            tail = (tail + 1) % items.length;  // 环形前进
            count++;
            notEmpty.signal();                 // 精确唤醒一个消费者
        } finally {
            lock.unlock();
        }
    }

    @SuppressWarnings("unchecked")
    T take() throws InterruptedException {
        lock.lockInterruptibly();
        try {
            while (count == 0) {
                notEmpty.await();              // 空：等「不空」这个条件
            }
            T item = (T) items[head];
            items[head] = null;                // 帮助 GC
            head = (head + 1) % items.length;
            count--;
            notFull.signal();                  // 精确唤醒一个生产者
            return item;
        } finally {
            lock.unlock();
        }
    }

    int size() {
        lock.lock();
        try { return count; } finally { lock.unlock(); }
    }
}

