// 两个线程交替打印 1..100：A 打奇数、B 打偶数
class AlternatingPrinter {
    private final Semaphore odd = new Semaphore(1);    // A 先跑
    private final Semaphore even = new Semaphore(0);   // B 等 A 交棒
    private int count = 1;                             // 只在持许可时读写

    void print() {
        new Thread(() -> run(odd, even), "A-odd").start();
        new Thread(() -> run(even, odd), "B-even").start();
    }

    private void run(Semaphore mine, Semaphore next) {
        try {
            while (true) {
                mine.acquire();                            // 等到轮到我
                if (count > 100) { next.release(); return; }  // ← 交棒后退出
                System.out.println(Thread.currentThread().getName() + ": " + count);
                count++;
                next.release();                            // 把机会交给对方
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

