class Aggregator {
    private final ExecutorService pool;

    Aggregator(ExecutorService bizPool) { this.pool = bizPool; }

    PageData aggregate(long userId) {
        // ① 三个任务并行发起，各自「包装成一定成功」
        CompletableFuture<Profile> profileF =
                CompletableFuture.supplyAsync(() -> loadProfile(userId), pool)
                        .handle((v, e) -> {
                            if (e != null) log.warn("profile failed, uid={}", userId, e);
                            return e == null ? v : Profile.empty();     // 兜底
                        });

        CompletableFuture<List<Order>> ordersF =
                CompletableFuture.supplyAsync(() -> loadOrders(userId), pool)
                        .handle((v, e) -> e == null ? v : List.<Order>of());

        CompletableFuture<List<Coupon>> couponsF =
                CompletableFuture.supplyAsync(() -> loadCoupons(userId), pool)
                        .handle((v, e) -> e == null ? v : List.<Coupon>of());

        // ② allOf 等全部，再逐个 join 收集
        CompletableFuture<PageData> all = CompletableFuture
                .allOf(profileF, ordersF, couponsF)
                .thenApply(v -> new PageData(
                        profileF.join(),      // 已完成，不会阻塞
                        ordersF.join(),
                        couponsF.join()));

        // ③ 整体超时 + 最终兜底
        return all.orTimeout(3, TimeUnit.SECONDS)               // JDK 9+
                  .exceptionally(e -> {
                      log.error("aggregate timeout/failed, uid={}", userId, e);
                      return PageData.empty();                   // 整页降级
                  })
                  .join();
    }
}

