// ✓ 修法：换成 ReentrantLock（持有者是虚拟线程，可安全卸载）
class GoodService {
    private final ReentrantLock lock = new ReentrantLock();

    String fetch(String url) {
        lock.lock();
        try {
            return httpGet(url);              // 阻塞时虚拟线程正常卸载
        } finally {
            lock.unlock();
        }
    }
}

