class DirClassLoader extends ClassLoader {
    private final Path root;

    DirClassLoader(Path root) { this.root = root; }
    DirClassLoader(Path root, ClassLoader parent) { super(parent); this.root = root; }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        Path file = root.resolve(name.replace('.', '/') + ".class");
        if (!Files.isRegularFile(file)) {
            throw new ClassNotFoundException(name);   // 契约：明确抛，不返回 null
        }
        try (InputStream in = Files.newInputStream(file)) {
            byte[] bytes = in.readAllBytes();
            Class<?> clazz = defineClass(name, bytes, 0, bytes.length);
            resolveClass(clazz);                      // 立刻链接，让验证错误在此暴露
            return clazz;
        } catch (IOException e) {
            throw new ClassNotFoundException(name, e);
        }
    }
}

// 打破委派的反序版本（仅示意，java.* 必须仍委派）
class ChildFirstLoader extends ClassLoader {
    @Override
    protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        if (name.startsWith("java.")) {                // 核心包不能抢
            return super.loadClass(name, resolve);
        }
        Class<?> c = findLoadedClass(name);
        if (c == null) {
            try {
                c = findClass(name);                    // 先自己找
            } catch (ClassNotFoundException ignored) {
                c = super.loadClass(name, resolve);     // 再委派
            }
        }
        if (resolve) resolveClass(c);
        return c;
    }
}
